INSERT INTO `job_posts` (`job_post_id`, `slug`, `title`, `department_id`, `position_id`, `employment_type`, `schedule`, `salary_min`, `salary_max`, `vacancies`, `filled_count`, `posted_date`, `status`, `requires_practical`, `requires_assessment`, `active`, `experience_level`, `education_level`, `summary`, `description`, `responsibilities_json`, `qualifications_json`, `skills_json`, `picture`, `created_at`, `updated_at`) VALUES
(1, 'bartender-1', 'Bartender', 2, 4, 'Full-time', 'Flexible Schedule', 190005.00, 230005.00, 25, 1, '2026-05-22', 'Open', 0, 0, 1, '1-2 Years', 'Bachelor\'s Degree', 'Oxford Suites Makati is seeking energetic and customer-focused Bartenders to join our vibrant Food & Beverage team. In this role, you will craft exceptional beverages while delivering warm Filipino hospitality in the heart of Makati\'s business district. Join us in creating memorable lounge and dining experiences for our guests.', 'Oxford Suites Makati is seeking energetic and customer-focused Bartenders to join our vibrant Food & Beverage team. In this role, you will craft exceptional beverages while delivering warm Filipino hospitality in the heart of Makati\'s business district. Join us in creating memorable lounge and dining experiences for our guests.', '[\"Prepare and serve high-quality alcoholic and non-alcoholic beverages following established recipes\",\"Maintain strict bar hygiene and clean work areas according to sanitation standards\",\"Operate POS systems accurately to process guest orders and manage cash handling\",\"Engage with guests warmly, provide beverage recommendations, and drive upselling opportunities\",\"Monitor bar stock levels, perform routine mise en place, and assist in inventory control\",\"Ensure responsible alcohol service and address guest inquiries with excellent communication\"]', '[\"Must hold a TESDA Bartending NC II or Food Handler Certificate\",\"Demonstrated knowledge in mixology, beverage preparation, and bar service\",\"Strong communication and customer service skills in a hospitality setting\",\"Willingness to work a flexible schedule, including night shifts, weekends, and holidays\",\"Familiarity with POS systems and basic inventory procedures is preferred\"]', '[\"Mixology\",\"Bar Hygiene\",\"Responsible Alcohol Service\",\"Customer Service\",\"Cash Handling\",\"POS Systems\",\"Upselling\",\"Communication\",\"Inventory Control\",\"Mise en Place\"]', 'job-post-pictures/eHC33w4haLFV8cmXrtwFzis3ij8fOF9BxBddk1gs.jpg', '2026-08-16 16:31:34', '2026-09-22 03:51:03'),
(2, 'line-cook', 'Line Cook', 3, 5, 'Full-time', 'Shifting Schedule', 16000.00, 20000.00, 4, 2, '2026-05-18', 'Open', 0, 0, 1, '1-2 Years', 'Vocational / TESDA', 'Prepare and cook menu items to standard, maintain station cleanliness and food safety compliance.', 'Prepare and cook menu items to standard, maintain station cleanliness and food safety compliance.', '[\"Prepare mise en place before each service.\",\"Cook and plate dishes to recipe standards.\",\"Maintain sanitation and food-safety compliance.\",\"Monitor inventory levels of station ingredients.\",\"Support banquet and room-service volume peaks.\"]', '[\"TESDA NC II in Cookery or equivalent culinary training.\",\"At least 1 year in a hotel or full-service restaurant kitchen.\",\"Valid food handler\'s certificate.\",\"Able to work under pressure during peak service.\"]', '[\"Food Safety\",\"HACCP\",\"Knife Skills\",\"Plating\",\"Teamwork\"]', NULL, '2026-08-16 16:31:34', '2026-08-25 19:31:17'),
(3, 'housekeeping-attendant', 'Housekeeping Attendant', 4, 7, 'Full-time', 'Shifting Schedule', 14000.00, 17000.00, 5, 3, '2026-05-10', 'Open', 0, 0, 1, 'No Experience', 'High School Graduate', 'Maintain guestroom cleanliness, linen turnover, and public-area presentation to brand standards.', 'Housekeeping Attendants keep guestrooms and public areas immaculate, restock amenities, and report maintenance issues. Full training is provided for applicants with no prior hotel experience.', '[\"Clean and prepare assigned guestrooms daily.\",\"Replenish linens, towels, and amenities.\",\"Report maintenance and lost-and-found items.\",\"Maintain housekeeping cart and supplies.\"]', '[\"High School Graduate.\",\"Physically fit and detail-oriented.\",\"Willing to work shifts including weekends and holidays.\"]', '[\"Attention to Detail\",\"Time Management\",\"Room Turnover\",\"Safety\"]', NULL, '2026-08-16 16:31:34', '2026-08-31 03:51:30'),
(4, 'restaurant-server', 'Restaurant Server', 2, 3, 'Full-time', 'Shifting Schedule', 15000.00, 18000.00, 4, 1, '2026-05-20', 'Closed', 0, 0, 0, 'No Experience', 'High School Graduate', 'Deliver warm, accurate table service across the dining room and banquet operations.', 'Restaurant Servers take orders, serve food and beverages, and ensure every guest leaves with a memorable dining experience at our all-day dining outlet.', '[\"Greet and seat guests warmly.\",\"Take and relay orders accurately to the kitchen.\",\"Serve food and beverages following service sequence.\",\"Handle billing and guest feedback.\"]', '[\"High School Graduate; hospitality training an advantage.\",\"Good communication skills in English and Filipino.\",\"Pleasant personality and grooming.\"]', '[\"Guest Service\",\"Upselling\",\"POS Systems\",\"Communication\"]', NULL, '2026-08-16 16:31:34', '2026-08-18 01:20:41'),
(5, 'bartender', 'Bartender', 2, 4, 'Part-time', 'Day Shift (8:00 AM - 5:00 PM)', 16000.00, 19000.00, 2, 0, '2026-05-15', 'Open', 0, 0, 1, '3-5 Years', 'Vocational / TESDA', 'Join the vibrant Food & Beverage team at Oxford Suites Makati as a Part-time Night Shift Bartender. Craft exceptional beverages while delivering warm Filipino hospitality to our guests at our premier Makati property. We are looking for two dedicated individuals to elevate our evening lounge experience.', 'Join the vibrant Food & Beverage team at Oxford Suites Makati as a Part-time Night Shift Bartender. Craft exceptional beverages while delivering warm Filipino hospitality to our guests at our premier Makati property. We are looking for two dedicated individuals to elevate our evening lounge experience.', '[\"Prepare and serve high-quality alcoholic and non-alcoholic beverages according to hotel standards\",\"Maintain cleanliness, bar hygiene, and proper sanitation across all counter and lounge areas\",\"Process guest orders and payments accurately using POS Systems and handle cash efficiently\",\"Engage with guests warmly, recommend beverage options, and practice effective upselling\",\"Monitor bar inventory, conduct regular stock checks, and manage mise en place efficiently\",\"Enforce responsible alcohol service guidelines to ensure guest safety and compliance\"]', '[\"Holder of TESDA Bartending NC II or Food Handler Certificate is preferred\",\"Prior experience as a bartender in a hotel, lounge, or upscale restaurant environment\",\"Solid understanding of mixology, beverage preparation, and responsible alcohol service\",\"Willingness to work night shifts, weekends, and holidays on a part-time arrangement\",\"Excellent interpersonal and communication skills with a customer-focused attitude\"]', '[\"Mixology\",\"Responsible Alcohol Service\",\"Bar Hygiene\",\"POS Systems\",\"Cash Handling\",\"Upselling\",\"Customer Service\",\"Communication\",\"Inventory Control\",\"Mise en Place\"]', NULL, '2026-08-16 16:31:34', '2026-09-22 03:53:48'),
(6, 'hr-assistant', 'HR Assistant', 5, 8, 'Full-time', 'Day Shift', 20000.00, 25000.00, 1, 0, '2026-05-08', 'Open', 0, 0, 1, '1-2 Years', 'Bachelor\'s Degree', 'Support recruitment, employee records, and HR document processing.', 'The HR Assistant supports end-to-end recruitment coordination, 201-file maintenance, and employee request processing for the property.', '[\"Coordinate interview schedules with department heads.\",\"Maintain complete and accurate 201 files.\",\"Process COE and employment verification requests.\",\"Assist in new-hire onboarding documentation.\"]', '[\"Bachelor\'s degree in Psychology, HR, or related field.\",\"At least 1 year HR experience.\",\"Strong organizational and documentation skills.\"]', '[\"Recruitment\",\"Documentation\",\"MS Office\",\"Confidentiality\"]', NULL, '2026-08-16 16:31:34', '2026-08-30 07:07:43'),
(15, 'guest-relations-officer', 'Guest Relations Officer', 1, 2, 'Full-time', 'Shifting Schedule', 20000.00, 28000.00, 1, 0, NULL, 'Open', 0, 0, 1, '1-2 Years', 'Bachelor\'s Degree', 'Join the Front Office team at Oxford Suites Makati as a Guest Relations Officer and be the face of our warm Filipino hospitality. In this role, you will deliver exceptional personalized service to our valued corporate and leisure guests in Makati\'s business district. We are seeking a dedicated hospitality professional who excels in creating memorable guest experiences.', 'Join the Front Office team at Oxford Suites Makati as a Guest Relations Officer and be the face of our warm Filipino hospitality. In this role, you will deliver exceptional personalized service to our valued corporate and leisure guests in Makati\'s business district. We are seeking a dedicated hospitality professional who excels in creating memorable guest experiences.', '[\"Welcome guests warmly upon arrival and assist with smooth check-in and check-out procedures\",\"Manage guest feedback, handle inquiries, and execute effective guest recovery when issues arise\",\"Provide personalized assistance and specialized care for VIP Handling throughout their stay\",\"Coordinate closely with Housekeeping and Front Office Operations to ensure prompt room readiness\",\"Promote hotel amenities and maximize revenue through active upselling of room upgrades and services\",\"Maintain complete and accurate guest interaction logs and records documentation in property systems\"]', '[\"Bachelor degree in Hospitality or related field, or BS Tourism\",\"TESDA Front Office NC II certification is highly preferred\",\"Demonstrated background in customer service, front desk, or guest relations roles\",\"Excellent verbal and written communication skills in English and Filipino\",\"Amenable to working on a shifting schedule, including weekends and holidays\"]', '[\"Guest Relations\",\"Front Office Operations\",\"Check-in \\/ Check-out\",\"VIP Handling\",\"Guest Recovery\",\"Complaint Handling\",\"Communication\",\"Upselling\",\"Customer Service\",\"Property Management Systems\"]', NULL, '2026-08-23 19:53:23', '2026-09-18 17:47:32'),
(16, 'front-desk-receptionist', 'Front Desk Receptionist', 1, 1, 'Full-time', 'Shifting Schedule', 18000.00, 25000.00, 2, 0, NULL, 'Open', 0, 0, 1, '1-2 Years', 'Bachelor\'s Degree', 'Join Oxford Suites Makati as a Front Desk Receptionist and become the face of our renowned warmth and Filipino hospitality in the heart of Makati\'s business district. In this dynamic role, you will deliver seamless guest experiences from arrival to departure while upholding our commitment to premier service standards. We are looking for dedicated professionals ready to excel in a full-time, shifting schedule setup.', 'Join Oxford Suites Makati as a Front Desk Receptionist and become the face of our renowned warmth and Filipino hospitality in the heart of Makati\'s business district. In this dynamic role, you will deliver seamless guest experiences from arrival to departure while upholding our commitment to premier service standards. We are looking for dedicated professionals ready to excel in a full-time, shifting schedule setup.', '[\"Perform efficient guest check-in and check-out operations following hotel standards\",\"Handle guest inquiries, reservations, and requests promptly with warm Filipino hospitality\",\"Manage cash handling, bill settlements, and accurate posting of charges using POS systems\",\"Resolve guest complaints and coordinate guest recovery efforts effectively\",\"Maintain accurate guest records documentation and proper turn-over during shift changes\",\"Promote hotel amenities and maximize revenue through proactive upselling techniques\"]', '[\"Bachelor degree in Hospitality or related field, or BS Tourism is preferred\",\"TESDA Front Office NC II certification is a strong advantage\",\"Prior experience in Front Office Operations or hotel guest services is preferred\",\"Demonstrated proficiency in Property Management Systems and MS Office\",\"Willingness to work on a shifting schedule, including weekends and holidays\"]', '[\"Check-in \\/ Check-out\",\"Front Office Operations\",\"Guest Relations\",\"Customer Service\",\"Communication\",\"Problem Solving\",\"Property Management Systems\",\"Upselling\",\"Cash Handling\"]', NULL, '2026-08-23 20:04:50', '2026-09-18 18:02:58'),
(18, 'floor-supervisor', 'Floor Supervisor', 4, 15, 'Full-time', 'Shifting Schedule', 0.00, 0.00, 1, 0, '2026-09-02', 'Closed', 0, 0, 0, NULL, NULL, 'Join Oxford Suites Makati as a Floor Supervisor to lead our housekeeping team in delivering exceptional guest experiences. You will oversee daily room turnover and ensure our high standards of cleanliness and warmth are consistently met. Be part of a premier all-suite hotel where Filipino hospitality shines brightest every single day.', 'Join Oxford Suites Makati as a Floor Supervisor to lead our housekeeping team in delivering exceptional guest experiences. You will oversee daily room turnover and ensure our high standards of cleanliness and warmth are consistently met. Be part of a premier all-suite hotel where Filipino hospitality shines brightest every single day.', '[\"Supervise daily housekeeping operations and room turnover across assigned floors\",\"Inspect guest rooms and public areas to ensure strict adherence to quality standards\",\"Conduct staff training and mentor housekeeping attendants for optimal performance\",\"Manage linen handling and maintain accurate inventory levels of cleaning supplies\",\"Report maintenance issues promptly and coordinate with engineering for timely repairs\",\"Handle guest requests and resolve complaints with genuine Filipino hospitality\"]', '[\"Holder of TESDA Housekeeping NC II certification\",\"Proven supervisory or leadership experience in hotel housekeeping operations\",\"Knowledgeable in chemical safety and proper housekeeping procedures\",\"Flexible and willing to work on a shifting schedule for full-time employment\",\"Possesses strong interpersonal and leadership abilities\"]', '[\"Housekeeping Operations\",\"Room Turnover\",\"Staff Training\",\"Chemical Safety\",\"Inventory Control\",\"Linen Handling\",\"Attention to Detail\",\"Guest Relations\",\"Problem Solving\"]', NULL, '2026-09-01 14:27:42', '2026-09-18 07:29:14'),
(19, 'floor-supervisor-1', 'Floor Supervisor', 4, 15, 'Full-time', 'Shifting Schedule', 15000.00, 30000.00, 1, 0, '2026-09-10', 'Open', 0, 0, 1, NULL, NULL, 'Join Oxford Suites Makati as a Floor Supervisor to lead our housekeeping team in delivering exceptional guest experiences. You will oversee daily room turnover and ensure our high standards of cleanliness and warmth are consistently met. Be part of a premier all-suite hotel where Filipino hospitality shines brightest every single day.', 'Join Oxford Suites Makati as a Floor Supervisor to lead our housekeeping team in delivering exceptional guest experiences. You will oversee daily room turnover and ensure our high standards of cleanliness and warmth are consistently met. Be part of a premier all-suite hotel where Filipino hospitality shines brightest every single day.', '[\"Supervise daily housekeeping operations and room turnover across assigned floors\",\"Inspect guest rooms and public areas to ensure strict adherence to quality standards\",\"Conduct staff training and mentor housekeeping attendants for optimal performance\",\"Manage linen handling and maintain accurate inventory levels of cleaning supplies\",\"Report maintenance issues promptly and coordinate with engineering for timely repairs\",\"Handle guest requests and resolve complaints with genuine Filipino hospitality\"]', '[\"Holder of TESDA Housekeeping NC II certification\",\"Proven supervisory or leadership experience in hotel housekeeping operations\",\"Knowledgeable in chemical safety and proper housekeeping procedures\",\"Flexible and willing to work on a shifting schedule for full-time employment\",\"Possesses strong interpersonal and leadership abilities\"]', '[\"Housekeeping Operations\",\"Room Turnover\",\"Staff Training\",\"Chemical Safety\",\"Inventory Control\",\"Linen Handling\",\"Attention to Detail\",\"Guest Relations\",\"Problem Solving\"]', NULL, '2026-09-09 08:22:06', '2026-09-09 08:22:06'),
(20, 'hr-administration-manager-1', 'HR & Administration Manager', 5, 14, 'Full-time', 'Shifting Schedule', 25000.00, 30000.00, 1, 0, '2026-09-10', 'Open', 0, 0, 1, NULL, NULL, 'Oxford Suites Makati is seeking a dedicated HR & Administration Manager to lead our human resources and administrative functions. You will play a vital role in championing our warm Filipino hospitality while maintaining operational excellence. Join our dynamic team in Makati\'s bustling business district and help shape our workforce culture.', 'Oxford Suites Makati is seeking a dedicated HR & Administration Manager to lead our human resources and administrative functions. You will play a vital role in championing our warm Filipino hospitality while maintaining operational excellence. Join our dynamic team in Makati\'s bustling business district and help shape our workforce culture.', '[\"Manage end-to-end recruitment support and talent acquisition processes\",\"Provide accurate payroll support and maintain meticulous employee records\",\"Coordinate staff training programs aligned with hospitality standards\",\"Ensure strict compliance with labor laws and company policies\",\"Oversee general administrative duties and office inventory control\",\"Handle employee relations, engagement activities, and grievance handling\"]', '[\"Proven experience in human resources and general administration management\",\"Possession of a valid First Aid Certificate is an advantage\",\"Strong knowledge of Philippine labor codes and employee relations\",\"Excellent interpersonal skills suitable for a premier hotel environment\"]', '[\"Communication\",\"Confidentiality\",\"Problem Solving\",\"Time Management\",\"MS Office\",\"Payroll Support\",\"Recruitment Support\",\"Records Documentation\",\"Staff Training\"]', NULL, '2026-09-09 08:23:41', '2026-09-22 03:46:55'),
(21, 'general-manager-1', 'General Manager', 5, 9, 'Full-time', 'Shifting Schedule', 15000.00, 20000.00, 1, 0, '2026-09-10', 'Open', 0, 0, 1, NULL, NULL, 'Oxford Suites Makati seeks an experienced General Manager to lead our administrative and operational teams. You will drive hotel performance while delivering our signature warm Filipino hospitality to every guest. Join our premier business district property and elevate our guest experience standards.', 'Oxford Suites Makati seeks an experienced General Manager to lead our administrative and operational teams. You will drive hotel performance while delivering our signature warm Filipino hospitality to every guest. Join our premier business district property and elevate our guest experience standards.', '[\"Oversee daily hotel operations across all administrative and service departments\",\"Ensure strict adherence to safety compliance and regulatory standards\",\"Lead staff training initiatives to maintain exceptional service delivery\",\"Manage budget allocation, inventory control, and financial reporting\",\"Handle escalated guest concerns with effective problem solving\",\"Drive revenue growth through strategic upselling and marketing efforts\"]', '[\"Proven leadership experience in hotel management or a similar executive role\",\"Degree in hospitality management, business administration, or relevant field\",\"Possession of a valid Food Handler Certificate for safety compliance oversight\",\"Demonstrated expertise in property management systems and hotel operations\"]', '[\"Hotel Operations\",\"Customer Service\",\"Problem Solving\",\"Staff Training\",\"Inventory Control\",\"Safety Compliance\",\"Upselling\",\"Communication\"]', NULL, '2026-09-09 08:33:21', '2026-09-17 19:15:34'),
(22, 'executive-housekeeper', 'Executive Housekeeper', 4, 13, 'Full-time', 'Shifting Schedule', 20000.00, 25000.00, 1, 0, '2026-09-18', 'Open', 0, 0, 1, NULL, NULL, 'Oxford Suites Makati is seeking a dedicated Executive Housekeeper to lead our housekeeping team in delivering pristine accommodations and warm Filipino hospitality. In this key executive role, you will oversee daily room turnovers, public area maintenance, and inventory management across our premier property. Join us in setting the standard for comfort and excellence in Makati\'s business district.', 'Oxford Suites Makati is seeking a dedicated Executive Housekeeper to lead our housekeeping team in delivering pristine accommodations and warm Filipino hospitality. In this key executive role, you will oversee daily room turnovers, public area maintenance, and inventory management across our premier property. Join us in setting the standard for comfort and excellence in Makati\'s business district.', '[\"Lead and manage daily housekeeping operations, room turnover, and public area cleanliness\",\"Oversee linen handling, chemical safety protocols, and inventory control for guest suites\",\"Prepare staff scheduling, conduct shift supervision, and lead regular staff training programs\",\"Conduct thorough inspections of guest rooms and hotel facilities to ensure top standards\",\"Address guest feedback and execute guest recovery measures for room-related concerns\",\"Ensure full safety compliance and proper maintenance of all housekeeping equipment\"]', '[\"Bachelor degree in Hospitality or related field preferred\",\"Proven experience in housekeeping management within a hotel or hospitality setting\",\"Must hold a TESDA Housekeeping NC II certification\",\"First Aid Certificate is an advantage\",\"Strong leadership, problem-solving, and team supervision skills\"]', '[\"Housekeeping Operations\",\"Attention to Detail\",\"Room Turnover\",\"Public Area Cleaning\",\"Linen Handling\",\"Chemical Safety\",\"Shift Supervision\",\"Staff Training\",\"Inventory Control\",\"Safety Compliance\"]', NULL, '2026-09-18 06:19:08', '2026-09-18 07:29:26');
